def replace_adjacent_non_coprimes(nums):
    from math import gcd
    stack=[]
    for value in nums:
        stack.append(value)
        while len(stack)>1:
            divisor=gcd(stack[-2],stack[-1])
            if divisor==1:break
            right=stack.pop();left=stack.pop();stack.append(left//divisor*right)
    return stack

